return {["shiti"]={["1"]={["answer"]=[[劈]],["audio"]=[[宫]],["choose1"]=[[劈]],["choose2"]=[[破]],["failText"]=[[你听到琴音后立马发招，但不知是何缘故，你打出的招式非但未能与琴音相和，反而有损自身气力，使得浑身经脉隐隐发痛。]],["id"]=1,["nothingText"]=[[你一时未能听清沐临烟的琴音，随意打出了几招，效果平平。]],["question"]=[[沐临烟信手微挑，清弹出一个音调——]],["trueText"]=[[你当即附和，将掌风与这琴音相融，朝着对方连续猛劈数下，威力倍增，直叫对方无力还击。]]},["10"]={["answer"]=[[穿]],["audio"]=[[羽]],["choose1"]=[[穿]],["choose2"]=[[破]],["failText"]=[[你听到琴音后立马发招，但不知是何缘故，你打出的招式非但未能与琴音相和，反而有损自身气力，使得浑身经脉隐隐发痛。]],["id"]=10,["nothingText"]=[[你一时未能听清沐临烟的琴音，随意打出了几招，效果平平。]],["question"]=[[沐临烟缓缓奏出两音，你忽觉眼前似有黄沙漫漫，又听她轻拍琴板，随之一段小调吟吟，如风沙即来，从缓至急，后以一重音而终——]],["trueText"]=[[琴音一出，你当即打出一道气劲，好趁对方御招时一掌穿过其右侧肩胛，拂击在人迎穴上，顿时使得对方头晕目眩，气血倍减。]]},["11"]={["answer"]=[[砍]],["audio"]=[[商]],["choose1"]=[[砍]],["choose2"]=[[穿]],["failText"]=[[你对琴音不甚熟悉，所以未能与沐临烟相和，最后只凭蛮劲儿出招。你虽能应对，但却隐隐觉得气息不畅。最终这琴音非但不能助你，还使得你心烦意乱。]],["id"]=11,["nothingText"]=[[你一时未能听清沐临烟的琴音，随意打出了几招，效果平平。]],["question"]=[[琴弦争鸣，沐临烟眸光熠熠，冲你浅浅一笑，捻动左弦——]],["trueText"]=[[你立马纵身一跃，自上而下朝着对方砍去，虽是拳掌出力，但那弦音就像一根根银线牵动着你的手脚，如有神助。]]},["12"]={["answer"]=[[破]],["audio"]=[[角]],["choose1"]=[[破]],["choose2"]=[[劈]],["failText"]=[[你眼见对方袭来，也顾不得琴音，只以平日所学武功应对，略有几分吃力。]],["id"]=12,["nothingText"]=[[你一时未能听清沐临烟的琴音，随意打出了几招，效果平平。]],["question"]=[[“六幺折断舞回春，燕鸿惊去弦不问。”沐临烟低吟一句，手腕来回扫动四弦，又陆续弹出几个快板，最终以一音渐淡——]],["trueText"]=[[你耳中忽闻弦音，再看对方已经朝你猛攻而来，你不急不缓，应和着琴音朗声道，“回马莫道长枪旧，迎破长空击悲流。”随后，你双掌并出，迅速擒住了对方的双臂，有力拔千斤之气，片刻就将其撂倒。]]},["2"]={["answer"]=[[砍]],["audio"]=[[商]],["choose1"]=[[御]],["choose2"]=[[砍]],["failText"]=[[你对琴音不甚熟悉，所以未能与沐临烟相和，最后只凭蛮劲儿出招。你虽能应对，但却隐隐觉得气息不畅。最终这琴音非但不能助你，还使得你心烦意乱。]],["id"]=2,["nothingText"]=[[你一时未能听清沐临烟的琴音，随意打出了几招，效果平平。]],["question"]=[[沐临烟五指一拢，快速轮拨数下后，转弦而奏，一连清音泛泛——]],["trueText"]=[[你立马纵身一跃，自上而下朝着对方砍去，虽是拳掌出力，但那弦音就像一根根银线牵动着你的手脚，如有神助。]]},["3"]={["answer"]=[[破]],["audio"]=[[角]],["choose1"]=[[穿]],["choose2"]=[[破]],["failText"]=[[你眼见对方袭来，也顾不得琴音，只以平日所学武功应对，略有几分吃力。]],["id"]=3,["nothingText"]=[[你一时未能听清沐临烟的琴音，随意打出了几招，效果平平。]],["question"]=[[沐临烟左手食指抹弦，右手不急不缓的轻轻一挑——]],["trueText"]=[[你耳中忽闻弦音，再看对方已经朝你猛攻而来，你不急不缓，应和着琴音朗声道，“回马莫道长枪旧